def solution(segments):
    # Brute force: selection sort by start (O(n^2)), then merge with a second pass.
    items = [list(seg) for seg in segments]
    ordered = []
    while items:
        best = 0
        for i in range(1, len(items)):
            if items[i][1] < items[best][1]:   # strict <, so ties keep input order
                best = i
        ordered.append(items.pop(best))
    result = []
    for seg in ordered:
        if result and result[-1][0] == seg[0] and seg[1] - result[-1][2] <= 1500:
            prev = result[-1]
            result[-1] = [prev[0], prev[1], max(prev[2], seg[2]), prev[3] + ' ' + seg[3]]
        else:
            result.append(seg)
    return result
